// 데모 모드 전용 유저/회원가입 API 목 구현

// 회원가입 (JOIN 페이지에서 "회원가입" 버튼 눌렀을 때 호출되는 기능)
export const signupAPI = {
  create: async (data) => {
    alert("데모 모드: 가입 처리는 시뮬레이션만 합니다.");
    // 실제라면 서버에서 생성된 유저 정보 내려줄 자리
    return {
      userId: data?.loginId || "demoUser",
      message: "SIGNUP_OK",
    };
  },
};

// 유저 정보 저장 같은 후처리 (원본 코드에서 createUserInfo 라는 이름으로 import하는 중)
// 여기서는 그냥 성공했다고 치고 끝낸다.
export async function createUserInfo(form) {
  // form 안에는 아마 {loginId, userName, ...} 이런 식으로 들어올 거다.
  // 우리는 실제로 DB에 넣지 않으니까 안내만.
  console.log("DEMO MODE createUserInfo()", form);
  alert("데모 모드: 유저 정보 로컬에만 반영됩니다.");
  return {
    result: "USERINFO_OK",
  };
}

// 로그인 이후 또는 레이아웃에서 헤더 표시용으로 불러오는 유저 정보
export async function getUserInfo() {
  // 백엔드 없이 화면에서만 쓸 가짜 사용자 정보
  return {
    userName: "데모사용자",
    loginId: "demoUser",
    role: "ADMIN",
  };
}
